#!/usr/bin/env python3
"""Write README.md: a one-line summary and a table of the skills in this repo.

A skill is a directory `<dir>/SKILL.md` at the repo root whose YAML
frontmatter has `name` and `description` keys. Rows are sorted by directory
name; a skill without `name` is listed under its directory name.
"""

import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
README = ROOT / "README.md"

HEADER = """\
<!-- Generated by scripts/gen_readme.py; edit that script, not this file. -->

# Skills

A collection of skills for Claude.

| Skill | Description |
|---|---|
"""


def read_frontmatter(path):
    """Return the top-level keys of the frontmatter of `path` as a dict of str.

    Supports `key: value` on one line and values continued on indented lines,
    including `>` and `|` block scalars; continuation lines are joined with
    single spaces. Returns {} if the file does not start with `---`.
    """
    lines = path.read_text(encoding="utf-8").splitlines()
    if not lines or lines[0].strip() != "---":
        return {}
    fields, key = {}, None
    for line in lines[1:]:
        if line.strip() == "---":
            break
        if line[:1] in (" ", "\t") and key is not None:
            fields[key] = (fields[key] + " " + line.strip()).strip()
        elif ":" in line:
            key, value = line.split(":", 1)
            key, value = key.strip(), value.strip()
            fields[key] = "" if value in (">", "|", ">-", "|-") else value.strip("\"'")
    return fields


def table_cell(text):
    """Return `text` safe to put in a Markdown table cell."""
    return text.replace("|", "\\|").replace("\n", " ")


def main():
    rows = []
    for skill_md in sorted(ROOT.glob("*/SKILL.md")):
        fields = read_frontmatter(skill_md)
        name = fields.get("name") or skill_md.parent.name
        link = skill_md.relative_to(ROOT).as_posix()
        description = table_cell(fields.get("description", ""))
        rows.append(f"| [{table_cell(name)}]({link}) | {description} |\n")
    README.write_text(HEADER + "".join(rows), encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
